using System.Text.Json;namespace PlayerOne.Windows.Services;
public sealed record AdvancedSettingsData(string StreamingFormat="auto",string BufferProfile="fast",bool KeepScreenOn=true,bool CompactOverlay=true,bool AutoNext=true,string CacheRefresh="background");
public static class AdvancedSettings{static string D=>Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Player One");static string P=>Path.Combine(D,"advanced.json");public static AdvancedSettingsData Load(){try{return File.Exists(P)?JsonSerializer.Deserialize<AdvancedSettingsData>(File.ReadAllText(P))??new():new();}catch{return new();}}public static void Save(AdvancedSettingsData x){Directory.CreateDirectory(D);File.WriteAllText(P,JsonSerializer.Serialize(x));}public static string? AlternateLiveUrl(string u){var q=u.IndexOf('?');var b=q>=0?u[..q]:u;var s=q>=0?u[q..]:"";if(b.EndsWith(".ts",StringComparison.OrdinalIgnoreCase))return b[..^3]+".m3u8"+s;if(b.EndsWith(".m3u8",StringComparison.OrdinalIgnoreCase))return b[..^5]+".ts"+s;return null;}}